INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Empyre: Dukes of the Far Frontier', 'Welcome to the bright lights and big city of New York in 1911. Never you mind the flooding. The water only goes up to the first floor. But not even the mighty waves of the Atlantic can drive New York into the depths. Now there is a new New York of self governing city-states perched atop buildings resting in the sea. This is your New York. You live in one of these City-States and now they need your help.' FROM games WHERE igdb_id = 198555 ON CONFLICT (game_id, language_code) DO NOTHING;
