INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Beltane: A strange encounter at Duloe - Stone Circle', 'Police and local people are baffled by phone cam footage that seems to show extraordinary phenomena over the 4000 year old stone circle, in Duloe, Cornwall. Experts are examining the footage, filmed by a local farmer, in the hope that sceptical eyes may reveal what the farmer describes as an "encounter". Is it a drone? Faked? Experimental military craft? Or a power generated by the stones themselves? Play to find out.' FROM games WHERE igdb_id = 206329 ON CONFLICT (game_id, language_code) DO NOTHING;
