INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Madohi Shiroki no Kamikakushi', '《雪境迷途遇仙踪》是由日本知名美少女游戏品牌 Lump of Sugar 制作的奇幻恋爱作品。本作由知名画师萌木原文武（代表作《游魂》系列）担当游戏原画与角色设计，由多位业内资深写手共同创作剧本，由知名音乐人新井健史担当音乐制作，主题歌由方糖社当家歌姬Kicco与新锐创作型歌手逢濑晶联袂献唱。' FROM games WHERE igdb_id = 188784 ON CONFLICT (game_id, language_code) DO NOTHING;
