INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Aster Force', 'Aster Force is a 3D sci-fi spaceship shooter game set in the far reaches of space. Players may choose from multiple ships to pilot, as they patrol and protect Sector 7184 from the sinister space pirates known as Specter. Join the crew of SS Gallaway to bring peace and order to the stars.' FROM games WHERE igdb_id = 195114 ON CONFLICT (game_id, language_code) DO NOTHING;
