INSERT INTO games (slug, igdb_id, release_date, metascore, cover_image_url, background_image_url, last_synced_at) VALUES ('omega-genesis', 249291, '2022-05-29', NULL, 'https://images.igdb.com/igdb/image/upload/t_cover_big/co6h5g.jpg', 'https://images.igdb.com/igdb/image/upload/t_1080p/scmhbo.jpg', NOW()) ON CONFLICT (igdb_id) DO NOTHING;
INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Omega Genesis', 'Ever since May 2022, a file named "Omega Genesis" has been spread in small forums, imageboards and communities throughout the internet. What seems like a cute puzzle game at first hides a variety of mysterious secrets around every corner. There is nothing known about the original creator "Samuel Lazarus", who (besides putting their name in the game) seems to have no digital footprint and is not interested in the discourse around the game. The earliest someone we contacted aquired the game was in early May, where they downloaded it from a link, posted in a thread on a popular imageboard. Up until now the only way to get the game was to get in contact with one of the few, who downloaded it. Now the game is finally available for everyone to explore for themselves.
