INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Malleus Maleficarum: The Witch of San Ignacio', 'World similar yet distinct from our own where the witch hunts were even deadlier than in our world''s history. The village of San Ignacio welcomes a new day, and with it, yet another witch trial. Another supposed witch is tried by the inquisition, yet these accusations involve strange circumstances that no one seems able to explain.' FROM games WHERE igdb_id = 318794 ON CONFLICT (game_id, language_code) DO NOTHING;
