INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Machine Yearning', 'You are a robot applying for a job. The poster of the job wants to keep humans from applying. To do this, they have prepared a captcha system with a new captcha every 10 seconds that only robots should be able to solve. Can you keep track of the language you’re building, or will your tiny human brain collapse under its own weight?' FROM games WHERE igdb_id = 245254 ON CONFLICT (game_id, language_code) DO NOTHING;
