INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Press W to Move Forward', 'Press W to Move Forward is a 5-minute experimental horror game exploring the rhetorics of progress, control, and societal pressure. Like the title suggests, the player''s only mode of control is through pressing W to progress the game with occasional mouse movements.' FROM games WHERE igdb_id = 222823 ON CONFLICT (game_id, language_code) DO NOTHING;
