INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Xross Dreams', 'Head-to-head arcade VS game, where all the characters are puzzle games, you control 2 at a time, and everybody does their own damage. A pre-, mid-, and post-apocalyptic fairy tale that teaches you telepathy if you decipher it properly. An climactic journey through stars and minds and trust.' FROM games WHERE igdb_id = 192593 ON CONFLICT (game_id, language_code) DO NOTHING;
