INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Fast & Furious Arcade', 'Fast & Furious is the 4th game in The Fast and The Furious arcade racing series. The last time the franchise graced the scene was with Fast & Furious Super Cars. In this game, players race a licensed, modded out supercar against the computer or a real rival, earning in-game cash and completing track-specific missions to further upgrade your vehicle. With 8 licensed supercars and 6 courses which span the world over, this is a guaranteed hit for any arcade.' FROM games WHERE igdb_id = 234789 ON CONFLICT (game_id, language_code) DO NOTHING;
