INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Blazing 8s', 'Blazing 8s is an Activity that we''ve developed here at Discord. It is our Crazy Eights-inspired card game that you can play with your friends! The rules are simple — on your turn, discard a card from your hand with the same suit or number as the previous card. Playing special cards allows you to skip other players, reverse the direction of play, and even swap hands with other players. The first person to discard all their cards wins!' FROM games WHERE igdb_id = 254426 ON CONFLICT (game_id, language_code) DO NOTHING;
