INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'ClayTown Horror', 'Well, welcome to ClayTown Horror. This here is a single-player horror game with a focus on story, and puzzles. You can expect an strange art style and chilling atmosphere, as well as intriguing riddles and puzzles throughout. Be sure to keep a eye out; you may find something we haven''t.' FROM games WHERE igdb_id = 217403 ON CONFLICT (game_id, language_code) DO NOTHING;
