INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Merge Design: Mansion Makeover', 'Merge Design is a very interesting casual merge game that combines decoration design, simulated construction and elimination gameplay to provide players with novel game content and gameplay designs. Here you can experience a completely different casual gameplay and feel your own merge challenge! Free choice of reward tasks, more surprise gifts, exclusive customize the appearance of the house, merge items to create a personalized living style, let''s start renovating your own mansion!' FROM games WHERE igdb_id = 246662 ON CONFLICT (game_id, language_code) DO NOTHING;
