INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Adventure: Limited Edition', 'This classic Atari 2600 title is the first ever action-adventure game, spawning an entire genre. The developer, Warren Robinett, famously hid his name inside a secret room – which became the first ever Easter Egg to be released in a console game. Adventure was introduced to a new generation of fans by the character James Halliday in the novel Ready Player One, who says "finding Robinett’s Easter Egg for the first time was one of the coolest videogaming experiences of my life.”' FROM games WHERE igdb_id = 210364 ON CONFLICT (game_id, language_code) DO NOTHING;
