INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Bloody Efforts', 'Play as a brave Warrior keen in his swordsmanship, a wise Sage spellcasting powerful Magic or an adventurous Bard healing wounded allies. Is that not your take? Then create your own Heroes! Set their Weapons, Skills, Passives and join the battle to prove your own hierarchy through Bloody Efforts.' FROM games WHERE igdb_id = 211473 ON CONFLICT (game_id, language_code) DO NOTHING;
