INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Rawbots', 'A universe where you can play with amazing robots that are designed, built and even programmed by you. Everything is a robot, doors, roads, walls, bridges, safes, traps, turrets, surveillance systems, etc. Build forts, towers and architect impressive structures to protect your planets and resources. You may play solo or with friends to infiltrate, conquer planets and gather resources.' FROM games WHERE igdb_id = 62969 ON CONFLICT (game_id, language_code) DO NOTHING;
