INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'Grim Quest: Origins', 'Grim Quest: Origins is a classic turn-based RPG / Dungeon Crawler with clean aesthetics and a retro vibe. It puts a lot of emphasis on atmosphere and immersion with lots of written text, carefully picked music, and fitting visuals that paint a colorful world of an exotic tropical archipelago. Some roguelike elements are thrown in for good measure. Reminiscent of pen and paper DnD.' FROM games WHERE igdb_id = 200238 ON CONFLICT (game_id, language_code) DO NOTHING;
