INSERT INTO game_translations (game_id, language_code, title, description) SELECT id, 'en', 'From the Sun to the Moon', 'Soleil (pronounced “soh-lay”) and her girlfriend Esmeray (pronounced “ehz-mer-ay”) have been together for almost three years! Leading up to their third year anniversary, Soleil decides the best way to celebrate would be to take Esmeray out on a date each day leading up to their anniversary! Will the dates be successful, or end in total failure? Play now to find out!' FROM games WHERE igdb_id = 256084 ON CONFLICT (game_id, language_code) DO NOTHING;
